// The first result lists every other section on the page, with a ready selector.
const first = $input.first().json
return (first.sections || []).filter(s => s.selector !== first.selector)
  .sort((a, b) => a.order - b.order).slice(0, 12)
  .map(s => ({ json: { url: first.url || 'https://linear.app', selector: s.selector, section: s.label }, pairedItem: { item: 0 } }))

// Each section files itself under the page; the newest link has them all.
const all = [...$('Turn the hero into code + find sections').all(), ...$input.all()].map(i => i.json)
const page = all.filter(r => r.pagePreviewUrl).pop()?.pagePreviewUrl
return [{ json: { pagePreviewUrl: page, sections: all.filter(r => r.code).length }, pairedItem: { item: 0 } }]
